std::vector<Node> nodes;
for (auto it = rt.finite_vertices_begin(); it != rt.finite_vertices_end(); ++it) {
    auto point = it->point();
    double x = point.x(), y = point.y(), z = point.z();
    Vector position(x, y, z);

    // Compute velocity from cell's dual power center
    auto cell = it->cell();
    Vector vel = velocity(cell);

    // Compute mass as inverse of power distance (or weight)
    double mass = it->weight();

    // Count adjacent edges below threshold to classify node type
    int edge_count = 0;
    for (auto eit = rt.incident_edges(it); eit != rt.incident_edges(); ++eit) {
        if (rt.is_infinite(eit->first)) continue;
        if (is_small_edge(rt, *eit, threshold)) {
            edge_count++;
        }
    }

    NodeType type = type_from_edge_count(edge_count);

    nodes.emplace_back(Node{position, vel, mass, type});
}
return nodes;

